insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23655')::uuid, md5('building-willy-brandt-strasse-23-20457')::uuid, '23655', 'kallmorgen-tower-tradition-trifft-moderne-23655', 'Kallmorgen Tower: Tradition trifft Moderne', 'Das markante, siebzehnstöckige Hochhaus in zentraler Innenstadtlage an der Willy-Brandt-Straße wird derzeitig komplett revitalisiert. Die U- und S-Bahnstationen Meßberg und …', 'Das markante, siebzehnstöckige Hochhaus in zentraler Innenstadtlage an der Willy-Brandt-Straße wird derzeitig komplett revitalisiert. Die U- und S-Bahnstationen Meßberg und Rathaus sind fußläufig schnell erreicht und sichern eine gute Anbindung an den ÖPNV. Die Büroflächen erschließen sich über einen neu gestalteten, repräsentativen Eingangsbereich mit zwei Fahrstühlen und modernem Lichtkonzept. Die hochwertige Ausstattung umfasst u.a. innenliegenden Sonnenschutz, Kühldeckensegel im jeweiligen Deckenfeld, 3-fach Verglasung, Küchenzeilen und separate WC-Einheiten. Die Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder stammen aus einer ähnlichen Fläche im Objekt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze', 'wasserblick']::text[], 462, 924, 'https://www.buerohamburg.de/objects/pdf/BHI_23655.pdf', null, 'filemaker', '23655') on conflict (id) do nothing;
