insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25688')::uuid, md5('building-essener-strasse-4-22419')::uuid, '25688', 'funktionelle-bueroflaeche-im-gruenen-valvo-park-25688', 'Funktionelle Bürofläche im grünen Valvo-Park', 'Das außergewöhnliche Gebäude befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg nur wenige Meter von der Langenhorner Chaussee …', 'Das außergewöhnliche Gebäude befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg nur wenige Meter von der Langenhorner Chaussee entfernt. Auf dem Gelände befinden sich zudem das Restaurant Marlin, welches u.a. ein preiswertes und abwechslungsreiches Mittagsmenü anbietet und die Fitnesskette Elixia, die auf ca. 4.000 qm über ein umfassendes Sportangebot inklusive Swimmingpool verfügt. Zur Ausstattung der Mieteinheit zählt u.a. ein Teppichbodenbelag, eine Einbauküche, sowie getrennte sanitäre Anlagen sind mehrfach vorhanden. Diese Innenbilder sind beispielhaft gewählt. Pkw-Stellplätze stehen auf Anfrage zur Anmietung bereit. Die Bilder sind beispielhaft gewählt und stammen aus einer ähnlichen Fläche im Gebäude.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['barrierefrei', 'stellplaetze']::text[], 229, 1119, 'https://www.buerohamburg.de/objects/pdf/BHI_25688.pdf', null, 'filemaker', '25688') on conflict (id) do nothing;
