insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25313')::uuid, md5('building-suederstrasse-24-20097')::uuid, '25313', 'gepflegte-bueroflaeche-in-zentraler-city-sued-lage-25313', 'Gepflegte Bürofläche in zentraler City-Süd-Lage', 'Das 7-geschossige, sehr gepflegte Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage der City Süd zwischen den Elbbrücken und der Hamburger Innenstadt unmittelbar …', 'Das 7-geschossige, sehr gepflegte Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage der City Süd zwischen den Elbbrücken und der Hamburger Innenstadt unmittelbar an der S-Bahnstation Hammerbrook. Diverse Cafés und Restaurants im nahen Umfeld sind in wenigen Gehminuten erreicht und ermöglichen abwechslungsreiche Mittagspausen. Zur aktuellen Ausstattung gehören u.a. Teppichfußboden, Bodentanks, außenliegender elektrischer Sonnenschutz, Deckenbeleuchtung, eine Pantry und separate WC-Einheiten. Die Innenansichten sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 562, 1874, 'https://www.buerohamburg.de/objects/pdf/BHI_25313.pdf', null, 'filemaker', '25313') on conflict (id) do nothing;
