insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-22976')::uuid, md5('building-caffamacherreihe-5-7-20355')::uuid, '22976', 'das-brahms-quartier-hochwertige-bueroflaechen-im-herzen-der-stadt-22976', 'Das Brahms Quartier: Hochwertige Büroflächen im Herzen der Stadt', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage nur wenige Meter vom Gänsemarkt entfernt. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und …', 'Das moderne Büro- und Geschäftsgebäude befindet sich in erstklassiger City-Lage nur wenige Meter vom Gänsemarkt entfernt. Vielseitige Einkaufsmöglichkeiten und diverse Cafés und Restaurants prägen das lebendige Umfeld. Die nahe gelegenen U- und S-Bahnstationen Gänsemarkt und Jungfernstieg sichern die Anbindung an das öffentliche Verkehrsnetz. Zur aktuellen Ausstattung der Bürofläche zählt ein hochwertiger Teppichbodenbelag, bodentiefe Fenster mit außenliegendem Sonnenschutz, Hohlraumboden, eine moderne Teeküche sowie getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenansichten stammen aus einer ähnlichen Fläche im Objekt. Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['barrierefrei', 'stellplaetze']::text[], 413, 1045, 'https://www.buerohamburg.de/objects/pdf/BHI_22976.pdf', null, 'filemaker', '22976') on conflict (id) do nothing;
