insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18978')::uuid, md5('building-blohmstrasse-10-14-21079')::uuid, '18978', 'wirtschaftliche-bueroflaeche-im-channel-harburg-18978', 'Wirtschaftliche Bürofläche im Channel-Harburg', 'Der architektonisch sehr ansprechende Neubau befindet sich in verkehrsgünstiger Lage von Hamburg-Harburg mit einer guten Anbindung an die Autobahn A1 sowie die Harburger Altstadt. …', 'Der architektonisch sehr ansprechende Neubau befindet sich in verkehrsgünstiger Lage von Hamburg-Harburg mit einer guten Anbindung an die Autobahn A1 sowie die Harburger Altstadt. Das Objekt verfügt über einen repräsentativen Eingangsbereich und ein lichtdurchflutetes, großzügiges Treppenhaus. Die Bürofläche ist unter anderem mit einem Fensterbrüstungskanal mit bereits integrierter EDV-Verkabelung, Pendelleuchten, innen liegendem Blendschutz sowie Teppichboden ausgestattet. Die Innenbilder sind beispielhaft gewählt. PKW-Stellplätze können nach Rücksprache angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 477, 2922, 'https://www.buerohamburg.de/objects/pdf/BHI_18978.pdf', null, 'filemaker', '18978') on conflict (id) do nothing;
