insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23594')::uuid, md5('building-glockengiesserwall-1-20095')::uuid, '23594', 'flexibel-gestaltbare-bueroflaeche-in-hamburgs-bester-geschaeftslage-23594', 'Flexibel gestaltbare Bürofläche in Hamburgs bester Geschäftslage', 'Das elegante Bürogebäude grenzt unmittelbar an die Mönckebergstraße. Diese Lage zeichnet sich durch ausgezeichnete Einkaufsmöglichkeiten aus und bietet eine Vielzahl …', 'Das elegante Bürogebäude grenzt unmittelbar an die Mönckebergstraße. Diese Lage zeichnet sich durch ausgezeichnete Einkaufsmöglichkeiten aus und bietet eine Vielzahl unterschiedlicher Cafés und Restaurants in direkter Nähe. Der gegenüberliegende Hauptbahnhof gewährleistet eine optimale Anbindung an den öffentlichen Nah- und Fernverkehr. Zur aktuellen Ausstattung zählen ein PVC-Bodenbelag in Holzoptik, eine Pantry und getrennte WC-Einheiten. Die weitere Aufteilung sowie Ausstattung der Mietfläche erfolgt in Absprache mit dem Vermieter. Die Innenbilder sind beispielhaft gewählt und stammen aus einer anderen Fläche im Objekt.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23594-1')::uuid, md5('property-23594')::uuid, 'Mietfläche', 981, 17, null, 'filemaker', '23594-1') on conflict (id) do nothing;
