insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23603')::uuid, md5('building-friedrich-ebert-damm-143-145-22047')::uuid, '23603', 'individuelle-bueroflaechen-im-azur-plaza-hamburg-23603', 'Individuelle Büroflächen im Azur Plaza Hamburg', 'Das in markanter Ecklage gelegene Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage von Hamburg Wandsbek mit einer guten Anbindung an das öffentliche …', 'Das in markanter Ecklage gelegene Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage von Hamburg Wandsbek mit einer guten Anbindung an das öffentliche Verkehrsnetz. Kleine Cafés, Restaurants und Unterhaltungsmöglichkeiten sind fußläufig erreichbar. Seine besondere Gestaltung hebt es gegenüber anderen Objekten in der Nachbarschaft hervor. Die Mietflächen werden in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet. Zur Standardausstattung zählt u.a. ein Textilbodenbelag, EDV gerechte Beleuchtung, Kabelkanäle, eine Teeküche sowie getrennte WC-Einheiten. Der Mietpreis richtet sich nach den jeweiligen Umbauwünschen. Die beigefügten Innenbilder sind beispielhaft gewählt und stammen aus einer anderen Fläche im Objekt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 302, 1061, 'https://www.buerohamburg.de/objects/pdf/BHI_23603.pdf', null, 'filemaker', '23603') on conflict (id) do nothing;
