insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24306')::uuid, md5('building-steindamm-72-86-20099')::uuid, '24306', 'moderne-bueroflaechen-mit-ausblick-24306', 'Moderne Büroflächen mit Ausblick!', 'Das Breeam-zertifizierte Bürogebäude Rasterwerk befindet sich im lebendigen Stadtteil St. Georg und wird aktuell umfassend revitalisiert, um ab Herbst 2025 seine neuen Mieter zu …', 'Das Breeam-zertifizierte Bürogebäude Rasterwerk befindet sich im lebendigen Stadtteil St. Georg und wird aktuell umfassend revitalisiert, um ab Herbst 2025 seine neuen Mieter zu begrüßen. Das direkte Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs sowie eine Vielzahl an Cafés und Restaurants. Die U-Bahnstation Lohmühlenstraße befindet sich quasi direkt vor dem Objekt und auch der Hauptbahnhof, mit Zugang zu allen U- und S-Bahnlinien sowie den Zügen der Deutschen Bahn, ist nach kurzem Fußweg erreichtinsert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24306-1')::uuid, md5('property-24306')::uuid, 'Mietfläche', 1065, 23.5, null, 'filemaker', '24306-1') on conflict (id) do nothing;
