insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24917')::uuid, md5('building-heidenkampsweg-51-57-20097')::uuid, '24917', 'bezugsfertige-bueroflaeche-zwischen-elbbruecken-und-city-24917', 'Bezugsfertige Bürofläche zwischen Elbbrücken und City', 'Das moderne 7-geschossige Bürogebäude befindet sich im Herzen der City-Süd. Die direkte Lage am Fleet verleiht dem Gebäude ein ansprechendes Ambiente. Die Anbindung an den ÖPNV …', 'Das moderne 7-geschossige Bürogebäude befindet sich im Herzen der City-Süd. Die direkte Lage am Fleet verleiht dem Gebäude ein ansprechendes Ambiente. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Hammerbrook gewährleistet. Auch die Autobahnauffahrt sowie die Hamburger Innenstadt mit diversen Geschäften des täglichen Bedarfs, Restaurants und Cafés sind schnell erreicht. Die hellen Büroräume sind unter anderem ausgestattet mit einem Teppichboden, einem Beleuchtungssystem sowie getrennten WC-Einheiten. Der weitere Ausbau und die Ausstattung erfolgen in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze können in der hauseigenen Tiefgarage angemietet werden. Diese Innenansichten sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 150, 1487, 'https://www.buerohamburg.de/objects/pdf/BHI_24917.pdf', null, 'filemaker', '24917') on conflict (id) do nothing;
