insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24288')::uuid, md5('building-grosse-theaterstrasse-31-35-20355')::uuid, '24288', 'modern-ausgebaute-bueroflaeche-in-ruhiger-citylage-24288', 'Modern ausgebaute Bürofläche in ruhiger Citylage', 'In bester Innenstadtlage, zwischen Dammtorstraße und Colonnaden, befindet sich dieser imposante Büroneubau. Die Anbindung an das öffentliche Verkehrsnetz ist durch die umliegenden …', 'In bester Innenstadtlage, zwischen Dammtorstraße und Colonnaden, befindet sich dieser imposante Büroneubau. Die Anbindung an das öffentliche Verkehrsnetz ist durch die umliegenden U- und S-Bahnstationen Jungfernstieg, Gänsemarkt und Stephansplatz sowie diverse Buslinien als sehr gut zu bezeichnen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24288-1')::uuid, md5('property-24288')::uuid, 'Mietfläche', 1086, 28.5, null, 'filemaker', '24288-1') on conflict (id) do nothing;
