insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24935')::uuid, md5('building-domstrasse-17-21-20457')::uuid, '24935', 'das-zuerich-haus-in-bester-city-lage-24935', 'Das Zürich-Haus in bester City-Lage', 'Das sehr repräsentative Gebäude befindet sich nur wenige Meter von dem Rathausmarkt entfernt und verfügt über zwei großzügige, glasüberdachte Innenhöfe sowie gläserne Aufzüge. Die …', 'Das sehr repräsentative Gebäude befindet sich nur wenige Meter von dem Rathausmarkt entfernt und verfügt über zwei großzügige, glasüberdachte Innenhöfe sowie gläserne Aufzüge. Die Aufteilung der hellen Mietfläche erfolgt in Abstimmung mit dem Mieter. Zur Ausstattung gehören u.a. ein hochwertiger Teppichbodenbelag, bodentiefe Fensterelemente, ein Hohlraumboden, getrennte WC-Einheiten eine abgehängte Decke mit integrierten Beleuchtungskörpern sowie eine ausgestattete Teeküche. Pkw-Stellplätze können auf Anfrage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 142, 1116, 'https://www.buerohamburg.de/objects/pdf/BHI_24935.pdf', null, 'filemaker', '24935') on conflict (id) do nothing;
