insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18879')::uuid, md5('building-essener-strasse-4-22419')::uuid, '18879', 'individuelle-buero-und-hallenflaeche-im-gruenen-valvo-park-18879', 'Individuelle Büro- und Hallenfläche im grünen Valvo-Park', 'Die hohe Sheddachhalle befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg, nur wenige Meter von der Langenhorner Chaussee …', 'Die hohe Sheddachhalle befindet sich auf dem Gelände des grünen und ruhigen Valvo-Parks am nördlichen Stadtrand von Hamburg, nur wenige Meter von der Langenhorner Chaussee entfernt. Auf dem Gelände befinden sich zudem das Restaurant Marlin, welches u.a. ein preiswertes und abwechslungsreiches Mittagsmenü anbietet und die Fitnesskette Elixia, die auf ca. 4.000 qm über ein umfassendes Sportangebot inklusive Swimmingpool verfügt. Die Büro- und Hallenfläche ist unter anderem ausgestattet mit Laminat und Teppichboden, Konferenzräumen, EDV-Verkabelung sowie einer Küche und getrennten WC-Einheiten. Eine Fläche im Kellergeschoss für Akten und Archivierung ist inklusive. PKW-Stellplätze können nach Anfrage auf dem Gelände zusätzlich angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['barrierefrei', 'erdgeschoss', 'stellplaetze']::text[], 195, 1119, 'https://www.buerohamburg.de/objects/pdf/BHI_18879.pdf', null, 'filemaker', '18879') on conflict (id) do nothing;
