insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25419')::uuid, md5('building-brooktorkai-20-20457')::uuid, '25419', 'moderne-bueroflaeche-in-der-hafen-city-25419', 'Moderne Bürofläche in der Hafen-City', 'Der markante Gebäudekomplex befindet sich nahe den Deichtorhallen am Eingang der HafenCity in prominenter Nachbarschaft zum Spiegel-Gebäude. Der nahe gelegene Überseeboulevard …', 'Der markante Gebäudekomplex befindet sich nahe den Deichtorhallen am Eingang der HafenCity in prominenter Nachbarschaft zum Spiegel-Gebäude. Der nahe gelegene Überseeboulevard sorgt für Zugang zu zahlreichen Geschäften des täglichen Bedarfs sowie einer Vielzahl an Restaurants und Cafés. Nach kurzem Fußweg erreicht man die U-Bahnstation Meßberg sowie den Hamburger Hauptbahnhof. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25419-1')::uuid, md5('property-25419')::uuid, 'Mietfläche', 1125, 25, null, 'filemaker', '25419-1') on conflict (id) do nothing;
