insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24866')::uuid, md5('building-kuehnehoefe-1-5-22761')::uuid, '24866', 'moderne-bueroflaeche-in-den-kuehnehoefen-mit-zwei-terrassen-24866', 'Moderne Bürofläche in den Kühnehöfen mit zwei Terrassen', 'Das markante Büro- und Geschäftsgebäude befindet sich auf dem Areal der ehemaligen Essigfabrik der Carl Kühne KG. Das sechsgeschossige Bürohaus verfügt über beste …', 'Das markante Büro- und Geschäftsgebäude befindet sich auf dem Areal der ehemaligen Essigfabrik der Carl Kühne KG. Das sechsgeschossige Bürohaus verfügt über beste Verkehrsanbindungen zur A7 und den öffentlichen Verkehrsmitteln durch die S-Bahnstation Diebsteich und Ottensen sowie diverse Buslinien. Das Umfeld bietet viele Geschäfte des täglichen Bedarfs. Diese Bürofläche ist bereits ausgebaut. Zur hochwertigen Ausstattung zählt u.a. eine Kühldecke, ein Hohlraumboden, moderne WC-Einheiten, eine Teeküche und teilweise bodentiefe Fenster, Deckenfluter sowie außenliegender elektrischer Sonnenschutz. Highlight sind drei großzügige Terrassen mit einer Fläche von ca. 181 qm welche mit 6,04 € pro Quadratmeter zur Gesamtmiete hinzugerechnet werden. PKW-Stellplätze können nach Rücksprache in der hauseigenen Tiefgarage angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['balkon-terrasse', 'stellplaetze']::text[], 295, 1129, 'https://www.buerohamburg.de/objects/pdf/BHI_24866.pdf', null, 'filemaker', '24866') on conflict (id) do nothing;
