insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24148')::uuid, md5('building-suederstrasse-63-20097')::uuid, '24148', 'hammerbrook-modernes-buero-im-zentrum-der-city-sued-24148', 'Hammerbrook: Modernes Büro im Zentrum der City-Süd', 'Das moderne Bürogebäude befindet sich nur wenige Meter von der S-Bahnstation Hammerbrook entfernt. Die repräsentative Bürofläche erstreckt sich über ein volles Geschoss. Zur …', 'Das moderne Bürogebäude befindet sich nur wenige Meter von der S-Bahnstation Hammerbrook entfernt. Die repräsentative Bürofläche erstreckt sich über ein volles Geschoss. Zur hochwertigen Ausstattung der Büroräume gehört u.a. ein Teppichboden, Brüstungskabelkanäle, ein außenliegender Sonnenschutz, eine voll eingerichtete Teeküche und getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Diese Innenbilder sind beispielhaft gewählt. Pkw-Stellplätze können auf Anfrage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 698, 2792, 'https://www.buerohamburg.de/objects/pdf/BHI_24148.pdf', null, 'filemaker', '24148') on conflict (id) do nothing;
